module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic s,
    input  logic w,
    output logic z
);

    logic state; // 0: State A, 1: State B
    logic [1:0] cnt; // 0, 1, 2
    logic [1:0] ones;
    logic z_reg;

    assign z = z_reg;

    always_ff @(posedge clk) begin
        if (reset) begin
            state <= 1'b0;
            cnt   <= 2'd0;
            ones  <= 2'd0;
            z_reg <= 1'b0;
        end else begin
            case (state)
                1'b0: begin // State A
                    z_reg <= 1'b0;
                    cnt   <= 2'd0;
                    ones  <= 2'd0;
                    if (s) begin
                        state <= 1'b1; // Transition to State B
                    end
                end

                1'b1: begin // State B
                    case (cnt)
                        2'd0: begin
                            cnt   <= 2'd1;
                            ones  <= {1'b0, w};
                            z_reg <= 1'b0;
                        end
                        2'd1: begin
                            cnt   <= 2'd2;
                            ones  <= ones + w;
                            z_reg <= 1'b0;
                        end
                        2'd2: begin
                            cnt   <= 2'd0;
                            if ((ones + w) == 2'd2) begin
                                z_reg <= 1'b1;
                            end else begin
                                z_reg <= 1'b0;
                            end
                            ones  <= 2'd0;
                        end
                        default: begin
                            cnt   <= 2'd0;
                            ones  <= 2'd0;
                            z_reg <= 1'b0;
                        end
                    endcase
                end
            endcase
        end
    end

endmodule

